mapper.select:
select sceneId,sceneName,effStatus,startDate,endDate,remark,is_tmpl, dataStatus,sceneType,sceneType2,riskType,suitProduct, ftrName from (select distinct a.scene_id as sceneId, a.scene_name as sceneName, a.eff_status as effStatus, a.start_date as startDate, a.end_date as endDate, a.remark, a.is_tmpl as is_tmpl, nvl2( (select a.scene_ftr_id from (select t.scene_ftr_id,row_number() over() as rownum from stt_scene_factor t where t.scene_id = a.scene_id and t.ftr_value is null) a where a.rownum < 2), '未准备', '已准备') as dataStatus, b.tips_value as sceneType, g.tips_value as sceneType2, c.tips_value as riskType, h.tips_value as suitProduct, (select LISTAGG(item_value, ',') WITHIN GROUP(ORDER BY item_code) from (select distinct g2.item_value, g2.item_code from stt_scene_tips g1, sys_datadict_list g2 where g1.scene_id = a.scene_id and g2.dict_code = 'FTR_RSK_TYPE2' and g2.item_code = g1.tips_value) ) as ftrName from stt_scene a left join stt_scene_tips b on a.scene_id = b.scene_id and b.dict_code = 'SCENE_TYPE' and b.tips_value = #{sceneType, jdbcType=VARCHAR} left join stt_scene_tips g on a.scene_id = g.scene_id and g.dict_code = 'SCENE_TYPE2' and g.tips_value = #{sceneType2, jdbcType=VARCHAR} left join stt_scene_tips c on a.scene_id = c.scene_id and c.dict_code = 'RISK_TYPE' and c.tips_value = #{riskType, jdbcType=VARCHAR} left join stt_scene_tips h on a.scene_id = h.scene_id and h.dict_code = 'OPENMODE' and h.tips_value = #{suitProduct, jdbcType=VARCHAR}
join stt_scene_ftrtips d on a.scene_id = d.scene_id and d.dict_code = 'FTR_RSK_TYPE2' and d.param_value = #{ftrId, jdbcType=VARCHAR}
and a.scene_id = #{sceneIds[0], jdbcType=VARCHAR}
and a.scene_id in
#{item}
and a.scene_name = #{sceneNames[0], jdbcType=VARCHAR}
and a.scene_name in
#{item}
and a.eff_status = #{effStatus, jdbcType=VARCHAR} and a.start_date <= to_date(#{startDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and a.end_date >= to_date(#{endDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') ) z
z.is_tmpl = #{isTmpl, jdbcType=VARCHAR} and z.riskType = #{riskType, jdbcType=VARCHAR} and z.sceneType = #{sceneType, jdbcType=VARCHAR} and z.sceneType2 = #{sceneType2, jdbcType=VARCHAR} and z.suitProduct = #{suitProduct, jdbcType=VARCHAR}
order by z.sceneId desc
